package org.kanger;
import java.nio.file.*;
import java.util.*;
import org.kanger.ContextDependentCutInspection.*;
import org.kanger.ContextDependentModelInspection.*;
import org.kanger.ContextDependentModelInspection.Function;
import org.kanger.ContextDependentModelInspection.Request;
import org.kanger.ContextDependentModelInspection.Result;
import org.kanger.ContextDependentReplayInspection.Policy;
import org.kanger.ContextProductionCapture.Source;
import org.kanger.interfaces.ITerm;
import org.kanger.units.*;

public final class ContextDependentModelRunner {
    private static int checks;
    private interface Attempt{void run()throws Exception;}
    private static void require(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
    private static void reject(Attempt a,String why)throws Exception{boolean no=false;try{a.run();}catch(Exception expected){no=true;}require(no,why);}
    private static Mind memory()throws Exception{User u=new User();Mind m=new Mind(u);u.setCurrentMind(m);return m;}
    private static Rule raw(Mind m,String text)throws Exception{return (Rule)m.compileLine(text,false,new LinkedList<ITerm>());}
    private static Policy policy(){return new Policy(2000000,1000,1000,64000000,200000);}
    private static Member member(Mind m,int id,boolean x)throws Exception{return new Member(m,ContextProductionInventory.inspect(m,new UUID(0,id),3,x,Collections.emptyList(),1000));}
    private static SemanticTermSnapshot constant(String literal)throws Exception{Mind m=memory();Rule r=raw(m,"!constant("+literal+");");return SemanticTermSnapshot.capture(r.getDomain().get(0).getValue(m));}
    private static Source source(Member m,Rule r){return new Source(m.inventory.context,3,r.getId(),m.inventory.localX,"inventory:"+m.inventory.fingerprint);}
    private static Request request(Map<String,Model> models){return new Request(new ContextDependentIterationInspection.Request(policy(),10000,10),models,20,100000,4000000,4000000);}
    private static Result inspect(Member x,Model model)throws Exception{return ContextDependentModelInspection.inspect(x,Collections.emptyList(),request(Collections.singletonMap(ContextDependentCutInspection.local(x.inventory.context),model)));}
    private static Map<Signature,Relation> rels(String[] names,int[] arities,boolean[] defaults){Map<Signature,Relation> relations=new LinkedHashMap<>();for(int i=0;i<names.length;i++)relations.put(new Signature(names[i],arities[i]),new Relation(defaults[i],Collections.emptyMap()));return relations;}
    private static Model uniform(List<SemanticTermSnapshot> points,SemanticTermSnapshot other,String[] names,int[] arities,boolean[] values,Map<Function,Choice> functions){return new Model(points,other,rels(names,arities,values),functions);}
    private static void incomplete(Result r,String phase,String why){require(r.status==Status.INCOMPLETE&&r.phase.equals(phase),why+" actual="+r.status+"/"+r.phase+"/"+r.reason);require(r.iteration==null&&r.originalRows==0&&r.finalObligations==0,"no successful original or final model prefix exposed");}
    private static void finiteAndAllOther()throws Exception{
        SemanticTermSnapshot one=constant("1"),two=constant("2");Mind m=memory();raw(m,"!seed(1);");raw(m,"!@x seed(x)->out(x);");Member x=member(m,1,true);Map<Signature,Relation> tables=new LinkedHashMap<>();Map<List<Integer>,Boolean> atOne=Collections.singletonMap(Collections.singletonList(0),true);tables.put(new Signature("seed",1),new Relation(false,atOne));tables.put(new Signature("out",1),new Relation(false,atOne));Model good=new Model(Collections.singletonList(one),two,tables,Collections.emptyMap());String before=x.inventory.fingerprint;Result r=inspect(x,good);require(r.status==Status.AUDITED_SUPPLIED&&r.originalRows==2&&r.finalObligations==4,"all original rows and repeated actual common/private occurrences independently evaluated");require(before.equals(ContextProductionInventory.inspect(m,x.inventory.context,3,true,Collections.emptyList(),1000).fingerprint),"model choice never writes native knowledge");
        Request lowFinal=new Request(request(Collections.singletonMap(ContextDependentCutInspection.local(x.inventory.context),good)).iteration,Collections.singletonMap(ContextDependentCutInspection.local(x.inventory.context),good),20,100000,4000000,1);incomplete(ContextDependentModelInspection.inspect(x,Collections.emptyList(),lowFinal),"actual-final-audit","separate final budget proves original-only success cannot certify final state");
        Model missing=new Model(Collections.emptyList(),two,rels(new String[]{"seed","out"},new int[]{1,1},new boolean[]{true,true}),Collections.emptyMap());incomplete(inspect(x,missing),"model-preflight","uniform shortcuts cannot skip actual constant coverage");Model duplicates=new Model(Arrays.asList(one,one),two,tables,Collections.emptyMap());incomplete(inspect(x,duplicates),"model-preflight","duplicate semantic points refused");Model badOther=new Model(Collections.singletonList(one),one,tables,Collections.emptyMap());incomplete(inspect(x,badOther),"model-preflight","ALL-other must have a concrete representative outside named points");
        Map<Signature,Relation> malformed=new LinkedHashMap<>(tables);malformed.put(new Signature("out",1),new Relation(false,Collections.singletonMap(Collections.singletonList(2),true)));incomplete(inspect(x,new Model(Collections.singletonList(one),two,malformed,Collections.emptyMap())),"model-preflight","out-of-domain exception refused before truth checks");incomplete(ContextDependentModelInspection.inspect(x,Collections.emptyList(),request(Collections.emptyMap())),"model-preflight","model for every exact scope mandatory");reject(()->good.relations.clear(),"model relation table map immutable");reject(()->good.relations.get(new Signature("seed",1)).exceptions.clear(),"model exceptions immutable");
        Mind all=memory();raw(all,"!@x seed(x);");raw(all,"!@x seed(x)->out(x);");Member ax=member(all,2,true);Model namedOnly=new Model(Collections.singletonList(one),two,tables,Collections.emptyMap());incomplete(inspect(ax,namedOnly),"original-audit","unmentioned values refute a named-only universal model");Model allTrue=uniform(Collections.emptyList(),two,new String[]{"seed","out"},new int[]{1,1},new boolean[]{true,true},Collections.emptyMap());Result accepted=inspect(ax,allTrue);require(accepted.status==Status.AUDITED_SUPPLIED,"default covers every unnamed admissible value");ContextDependentProductionInspection.Row actual=accepted.iteration.checked.barriers.get(1).cuts.values().iterator().next().products.get(0);reject(()->ContextDependentModelAudit.unit(actual,namedOnly,ContextGroundProductionRounds.budget(100000)),"independent actual-carrier odometer rejects false ALL-other interpretation");ContextDependentModelAudit.unit(actual,allTrue,ContextGroundProductionRounds.budget(100000));require(true,"independent actual-carrier truth accepts all-value interpretation");
        Map<Signature,Relation> falseOut=new LinkedHashMap<>(tables);falseOut.put(new Signature("out",1),new Relation(false,Collections.emptyMap()));Model wrong=new Model(Collections.singletonList(one),two,falseOut,Collections.emptyMap());incomplete(inspect(x,wrong),"original-audit","failed supplied model is incomplete, not an inconsistency proof");reject(()->ContextDependentModelAudit.unit(r.iteration.checked.barriers.get(1).cuts.values().iterator().next().products.get(0),wrong,ContextGroundProductionRounds.budget(100000)),"direct actual signed carrier false case is rejected independently of original audit");
    }
    private static void BooleanOracle()throws Exception{
        SemanticTermSnapshot other=constant("99");for(int model=0;model<8;model++){Mind m=memory();raw(m,"!a()&&b()->r();");String[] names={"a","b","r"};boolean[] truth=new boolean[3];for(int i=0;i<3;i++){truth[i]=(model&(1<<i))!=0;raw(m,"!"+(truth[i]?"":"~")+names[i]+"();");}Member x=member(m,10+model,true);Model chosen=uniform(Collections.emptyList(),other,names,new int[]{0,0,0},truth,Collections.emptyMap());Result r=inspect(x,chosen);require(r.status==((!truth[0]||!truth[1]||truth[2])?Status.AUDITED_SUPPLIED:Status.REFUTED),"independent Boolean interpretation oracle "+model);if(r.status==Status.REFUTED)require(r.iteration.status==ContextDependentIterationInspection.Status.COLLISION,"REFUTED requires actual sourced refutation, never model rejection");}
    }
    private static void dependencyModels()throws Exception{
        List<SemanticTermSnapshot> points=Arrays.asList(constant("1"),constant("2"));SemanticTermSnapshot other=constant("3");
        for(boolean dependsOnB:new boolean[]{false,true}){
            Mind m=memory();Rule seed=raw(m,dependsOnB?"!@a @b $u rel(a,u,b);":"!@a $u @b rel(a,u,b);");raw(m,dependsOnB?"!@a @u ~(rel(a,u,1)&&rel(a,u,2));":"!@u ~(rel(1,u,1)&&rel(2,u,1));");Member x=member(m,dependsOnB?31:30,true);Map<List<Integer>,Boolean> trueRel=new LinkedHashMap<>();for(int a=0;a<3;a++)for(int b=0;b<3;b++)trueRel.put(Arrays.asList(a,dependsOnB?b:a,b),true);Map<List<Integer>,Integer> fn=new LinkedHashMap<>();if(dependsOnB){for(int a=0;a<3;a++)for(int b=0;b<2;b++)fn.put(Arrays.asList(a,b),b);}else{fn.put(Collections.singletonList(0),0);fn.put(Collections.singletonList(1),1);}Function key=new Function(source(x,seed),dependsOnB?2:1);Map<Function,Choice> functions=Collections.singletonMap(key,new Choice(dependsOnB?2:1,2,fn));Model model=new Model(points,other,Collections.singletonMap(new Signature("rel",3),new Relation(false,trueRel)),functions);Result result=inspect(x,model);require(result.status==Status.AUDITED_SUPPLIED,"explicit all-value model distinguishes preceding/later dependency scopes "+result.phase+"/"+result.reason);require(result.finalObligations>0,"signed residual actual carriers were evaluated");Map<Function,Choice> malformed=Collections.singletonMap(key,new Choice(dependsOnB?1:2,2,Collections.emptyMap()));incomplete(inspect(x,new Model(points,other,model.relations,malformed)),"model-preflight","function arity cannot introduce later dependency or drop preceding coordinates");
        }
        Mind conflict=memory();raw(conflict,"!@a $u @b rel(a,u,b);");raw(conflict,"!@a @u ~(rel(a,u,1)&&rel(a,u,2));");Member bad=member(conflict,32,true);Result refuted=ContextDependentModelInspection.inspect(bad,Collections.emptyList(),request(Collections.emptyMap()));require(refuted.status==Status.REFUTED&&refuted.phase.equals("sourced-refutation"),"known missing native conflict independently refuted before considering supplied model");
        for(int width:new int[]{1,7,17,65}){
            Mind m=memory();StringBuilder prefix=new StringBuilder(),args=new StringBuilder();for(int i=0;i<width;i++){prefix.append("@x").append(i).append(' ');if(i>0)args.append(',');args.append('x').append(i);}Rule seed=raw(m,"!"+prefix+"$u rel("+args+",u);");raw(m,"!"+prefix+"@u rel("+args+",u)->out("+args+",u);");Member x=member(m,100+width,true);Model model=uniform(Collections.emptyList(),other,new String[]{"rel","out"},new int[]{width+1,width+1},new boolean[]{true,true},Collections.singletonMap(new Function(source(x,seed),width),new Choice(width,0,Collections.emptyMap())));Result result=inspect(x,model);require(result.status==Status.AUDITED_SUPPLIED&&result.finalObligations>0,"uniform full-domain shortcut keeps whole source and rank validation at width "+width);Model wrong=uniform(Collections.emptyList(),other,new String[]{"rel","out"},new int[]{width+1,width+1},new boolean[]{true,true},Collections.singletonMap(new Function(source(x,seed),width),new Choice(width+1,0,Collections.emptyMap())));incomplete(inspect(x,wrong),"model-preflight","uniform relation cannot conceal a malformed dependency rank");
        }
    }
    private static void functionsAndScopes()throws Exception{
        SemanticTermSnapshot one=constant("1"),two=constant("2");Mind m=memory();Rule p=raw(m,"!$u p(u);"),q=raw(m,"!$v q(v);");Member x=member(m,201,true);Map<Function,Choice> functions=new LinkedHashMap<>();functions.put(new Function(source(x,p),0),new Choice(0,0,Collections.emptyMap()));functions.put(new Function(source(x,q),0),new Choice(0,0,Collections.emptyMap()));Model sameValue=uniform(Collections.singletonList(one),two,new String[]{"p","q"},new int[]{1,1},new boolean[]{true,true},functions);require(inspect(x,sameValue).status==Status.AUDITED_SUPPLIED,"distinct witness declarations may choose the same actual model value");Map<Function,Choice> missing=new LinkedHashMap<>(functions);missing.remove(new Function(source(x,q),0));incomplete(inspect(x,uniform(Collections.singletonList(one),two,new String[]{"p","q"},new int[]{1,1},new boolean[]{true,true},missing)),"model-preflight","every original declaration remains required even under uniform truth");
        Mind xm=memory(),am=memory(),bm=memory();raw(xm,"!anchor(1);");raw(am,"!p(1);");raw(bm,"!~p(1);");Member xx=member(xm,211,true),a=member(am,212,false),b=member(bm,213,false);Cut ca=new Cut(null,Collections.singletonList(a)),cb=new Cut(null,Collections.singletonList(b));Map<String,Model> models=new LinkedHashMap<>();models.put(ContextDependentCutInspection.local(xx.inventory.context),uniform(Collections.singletonList(one),two,new String[]{"anchor"},new int[]{1},new boolean[]{true},Collections.emptyMap()));models.put(ca.key,uniform(Collections.singletonList(one),two,new String[]{"anchor","p"},new int[]{1,1},new boolean[]{true,true},Collections.emptyMap()));models.put(cb.key,uniform(Collections.singletonList(one),two,new String[]{"anchor","p"},new int[]{1,1},new boolean[]{true,false},Collections.emptyMap()));Result independent=ContextDependentModelInspection.inspect(xx,Arrays.asList(cb,ca),request(models));require(independent.status==Status.AUDITED_SUPPLIED&&independent.originalRows==5,"independent A/B models can disagree while each satisfies X");Result trust=ContextDependentModelInspection.inspect(xx,Collections.singletonList(new Cut("both",Arrays.asList(a,b))),request(Collections.emptyMap()));require(trust.status==Status.REFUTED,"whole physical TRUST cut cannot choose separate contradictory interpretations");
    }
    private static void importedFunctions()throws Exception{
        SemanticTermSnapshot one=constant("1"),two=constant("2");Mind xm=memory(),am=memory(),bm=memory();raw(xm,"!@x rel(x)->out(x);");raw(am,"!anchor(1);");Rule seed=raw(bm,"!$u rel(u);");Member x=member(xm,221,true),a=member(am,222,false),b=member(bm,223,false);Cut ca=new Cut(null,Collections.singletonList(a)),cb=new Cut(null,Collections.singletonList(b));Map<Function,Choice> function=Collections.singletonMap(new Function(source(b,seed),0),new Choice(0,0,Collections.emptyMap()));Map<String,Model> models=new LinkedHashMap<>();String local=ContextDependentCutInspection.local(x.inventory.context);models.put(local,uniform(Collections.singletonList(one),two,new String[]{"rel","out"},new int[]{1,1},new boolean[]{false,true},function));models.put(ca.key,uniform(Collections.singletonList(one),two,new String[]{"rel","out","anchor"},new int[]{1,1,1},new boolean[]{false,true,true},function));models.put(cb.key,uniform(Collections.singletonList(one),two,new String[]{"rel","out"},new int[]{1,1},new boolean[]{true,true},function));Result r=ContextDependentModelInspection.inspect(x,Arrays.asList(ca,cb),request(models));require(r.status==Status.AUDITED_SUPPLIED&&r.finalObligations==10,"common foreign function is interpreted in every actual receiving cut without importing its original formula");require(r.iteration.frontier.common.get(0).arguments.get(0).symbolSource.equals(source(b,seed)),"actual carrier retains foreign declaration Source");Map<String,Model> missing=new LinkedHashMap<>(models);missing.put(local,uniform(Collections.singletonList(one),two,new String[]{"rel","out"},new int[]{1,1},new boolean[]{false,true},Collections.emptyMap()));incomplete(ContextDependentModelInspection.inspect(x,Arrays.asList(ca,cb),request(missing)),"model-preflight","final-only imported function cannot disappear from the receiving model manifest");
    }
    private static void nestedEvaluation()throws Exception{
        Mind m=memory();Rule seed=raw(m,"!@x $u rel(x,u);");raw(m,"!p(1);");raw(m,"!@a @b rel(a,b)&&p(a)->q(b);");raw(m,"!@a @b rel(a,b)&&q(a)->r(b);");Member x=member(m,231,true);Map<Signature,Relation> relations=new LinkedHashMap<>();Map<List<Integer>,Boolean> rel=new LinkedHashMap<>();rel.put(Arrays.asList(0,1),true);rel.put(Arrays.asList(1,2),true);rel.put(Arrays.asList(2,2),true);relations.put(new Signature("rel",2),new Relation(false,rel));relations.put(new Signature("p",1),new Relation(false,Collections.singletonMap(Collections.singletonList(0),true)));relations.put(new Signature("q",1),new Relation(false,Collections.singletonMap(Collections.singletonList(1),true)));relations.put(new Signature("r",1),new Relation(false,Collections.singletonMap(Collections.singletonList(2),true)));Function f=new Function(source(x,seed),1);Model model=new Model(Arrays.asList(constant("1"),constant("2")),constant("3"),relations,Collections.singletonMap(f,new Choice(1,2,Collections.singletonMap(Collections.singletonList(0),1))));Result result=inspect(x,model);require(result.status==Status.AUDITED_SUPPLIED,"independent original and final checks evaluate nonconstant functions over ALL-other defaults");ContextDependentProductionInspection.Row row=result.iteration.frontier.common.stream().filter(r->r.predicate.equals("r")).findFirst().get();require(row.arguments.get(0).kind==ContextDependentProductionInspection.Kind.APPLICATION&&row.arguments.get(0).arguments.get(0).kind==ContextDependentProductionInspection.Kind.APPLICATION,"actual final graph contains nested dependency applications");ContextDependentModelAudit.unit(row,model,ContextGroundProductionRounds.budget(100000));require(true,"bottom-up actual evaluation composes f(f(1))");Model wrong=new Model(model.points,model.otherRepresentative,relations,Collections.singletonMap(f,new Choice(1,0,Collections.emptyMap())));reject(()->ContextDependentModelAudit.unit(row,wrong,ContextGroundProductionRounds.budget(100000)),"nested actual evaluation rejects a different function interpretation");
    }
    public static void main(String[] args){try{System.setProperty("user.home",Files.createTempDirectory("dependent-model-").toString());finiteAndAllOther();BooleanOracle();dependencyModels();functionsAndScopes();importedFunctions();nestedEvaluation();checks+=org.kanger.storage.dumb2.ContextDependentModelProviderCases.run();System.out.println("CONTEXT_DEPENDENT_MODEL_PASS checks="+checks);System.exit(0);}catch(Throwable t){t.printStackTrace();System.exit(1);}}
}
